            resultSyncData = UpdateSyncLiveCasinoAfterCopy(criteria);

            if (resultSyncData.IsSuccessful == false)
            {
                resultMessage = string.Join(null, new string[] { resultMessage, "<div>", resultSyncData.Message, "</div>" });
